heuristic.toad_enforcement:

// WRONG (AI SLOP):
circle #ambientGlow { at: center; size: 800px; fill: radial(#8B5CF6, transparent); blur: 120px; }

// CORRECT (PROFESSIONAL LIGHTING):
rect #card {
  fill: #131722;
  border: 1px solid alpha(#FFFFFF, 0.08);
  shadow: 0 20px 40px alpha(#000000, 0.4);
}


// WRONG (AI SLOP GLASS OVERDOSE):
rect #slopCard {
  fill: alpha(#FFFFFF, 0.05);
  border: 1px solid alpha(#FFFFFF, 0.15);
  radius: 32px;
  blur: 20px;
}

// CORRECT (PROFESSIONAL OPAQUE DESIGN):
rect #solidCard {
  fill: #1E293B;
  border: 1px solid #334155;
  radius: 8px;
  shadow: 0 4px 12px alpha(#000000, 0.08);
}


// WRONG (AI SLOP HORROR VACUI: EVERYTHING OVERPACKED):
stack #clutteredHero {
  badge #b1 { text "AI Powered" {} }
  badge #b2 { text "Next-Gen" {} }
  badge #b3 { text "Zero Latency" {} }
  text #h1 { "Supercharge Everything" {} }
  text #sub { "Lorem ipsum dolor sit amet..." {} }
  rect #stat1 { text "99.9% Uptime" {} }
  rect #stat2 { text "10x Speed" {} }
  rect #stat3 { text "Zero Cost" {} }
  // 15 more auxiliary mini-cards...
}

// CORRECT (REFINED REDUCTION & NEGATIVE SPACE):
stack #calmHero {
  gap: 32px;
  text #headline {
    size: 64px;
    font-weight: 800;
    "Cloud ERP without bureaucratic friction."
  }
  text #sub {
    size: 20px;
    color: #64748B;
    width: 600px;
    "Automated accounting and inventory management for mid-market teams."
  }
  rect #ctaButton {
    fill: #6D213F;
    radius: 9999px;
    padding: 16px 36px;
    text "Start Free Trial" { color: #FFFFFF; font-weight: 600; }
  }
}
